        val rows=grid.size;
        val columns=grid[0].size;
        val prefix=Array(rows+1){
            IntArray(columns+1)
        };
        val cover=Array(rows+1){
            IntArray(columns+1)
        };
        for(r in 0 until rows)for(c in 0 until columns)prefix[r+1][c+1]=grid[r][c]+prefix[r][c+1]+prefix[r+1][c]-prefix[r][c];
        for(r in 0..rows-stampHeight)for(c in 0..columns-stampWidth){
            val bottom=r+stampHeight;
            val right=c+stampWidth;
